function playMacChime() {
  try {
    const audioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!audioContextClass) return;
    const ctx = new audioContextClass();
    if (ctx.state === "suspended") {
      ctx.resume().catch(() => {});
    }
    const frequencies = [370, 554.37, 740, 1108.73];
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);
    const startTime = ctx.currentTime;
    masterGain.gain.setValueAtTime(0.0001, startTime);
    masterGain.gain.exponentialRampToValueAtTime(0.3, startTime + 0.08);
    masterGain.gain.exponentialRampToValueAtTime(0.0001, startTime + 2.0);
    frequencies.forEach((freq) => {
      const osc = ctx.createOscillator();
      osc.type = "sine";
      osc.frequency.setValueAtTime(freq, startTime);
      osc.connect(masterGain);
      osc.start(startTime);
      osc.stop(startTime + 2.1);
    });
  } catch (error) {
    return;
  }
}

function playMacBootSplash() {
  return new Promise((resolve) => {
    const overlay = createElement("div", {
      styles: {
        position: "fixed",
        inset: "0",
        background: "#000000",
        zIndex: "2147483640",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        userSelect: "none",
        transition: "opacity 0.45s ease",
        opacity: "0"
      }
    });

    overlay.innerHTML = `
      <svg viewBox="0 0 384 512" width="76" height="100" style="fill:#ffffff;margin-bottom:48px;">
        <path d="${APPLE_SVG_PATH}"/>
      </svg>
      <div style="width:210px;height:5px;background:rgba(255,255,255,0.22);border-radius:3px;overflow:hidden;">
        <div id="mac-boot-bar" style="width:0%;height:100%;background:#ffffff;border-radius:3px;transition:width 1.7s cubic-bezier(0.16,1,0.3,1);"></div>
      </div>
    `;

    (document.body || document.documentElement).appendChild(overlay);
    playMacChime();

    requestAnimationFrame(() => {
      overlay.style.opacity = "1";
      const bar = $("#mac-boot-bar", overlay);
      if (bar) bar.style.width = "100%";
    });

    setTimeout(() => {
      overlay.style.opacity = "0";
    }, 1650);

    setTimeout(() => {
      if (overlay.parentNode) {
        overlay.parentNode.removeChild(overlay);
      }
      resolve();
    }, 2100);
  });
}

function playKaliBootSplash() {
  return new Promise((resolve) => {
    const overlay = createElement("div", {
      styles: {
        position: "fixed",
        inset: "0",
        background: "#090d14",
        zIndex: "2147483640",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "'JetBrains Mono', monospace",
        userSelect: "none",
        transition: "opacity 0.45s ease",
        opacity: "0"
      }
    });

    overlay.innerHTML = `
      <svg viewBox="0 0 24 24" width="100" height="100" style="fill:#00e5ff;filter:drop-shadow(0 0 16px rgba(0,229,255,0.7));margin-bottom:24px;">
        <path d="${KALI_DRAGON_PATH}"/>
      </svg>
      <div style="letter-spacing:8px;font-weight:700;color:#e6edf3;font-size:20px;margin-bottom:24px;">KALI LINUX</div>
      <div style="width:240px;height:4px;background:rgba(0,229,255,0.18);border:1px solid rgba(0,229,255,0.35);box-shadow:0 0 10px rgba(0,229,255,0.25);border-radius:2px;overflow:hidden;margin-bottom:20px;">
        <div id="kali-boot-bar" style="width:0%;height:100%;background:#00e5ff;box-shadow:0 0 8px rgba(0,229,255,0.8);transition:width 1.5s cubic-bezier(0.16,1,0.3,1);"></div>
      </div>
      <div style="font-size:11px;color:#00e5ff;letter-spacing:1px;">[ OK ] Reached target Graphical Interface</div>
    `;

    (document.body || document.documentElement).appendChild(overlay);

    requestAnimationFrame(() => {
      overlay.style.opacity = "1";
      const bar = $("#kali-boot-bar", overlay);
      if (bar) bar.style.width = "100%";
    });

    setTimeout(() => {
      overlay.style.opacity = "0";
    }, 1550);

    setTimeout(() => {
      if (overlay.parentNode) {
        overlay.parentNode.removeChild(overlay);
      }
      resolve();
    }, 2000);
  });
}

export function playOsBootSplash(mode) {
  if (mode === "mac") {
    return playMacBootSplash();
  }
  if (mode === "kali") {
    return playKaliBootSplash();
  }
  return Promise.resolve();
}
